/**
 * Портрет участника ША'26 — данные из таблиц организаторов:
 * «Копия Портрет Участника ША'26.xlsx» (листы «анкета», «дз», «цо », «собес»,
 * «вопросы анкеты») и «Прорабатываем ДЗ | Методистики'26.xlsx» (задания ДЗ и
 * шкала ДЗ). Тексты — как в таблицах, исправлены только явные опечатки.
 * Столбцы «0…6» таблиц — баллы: расшифровка стоит на том балле, где она в
 * таблице, верх шкалы — последний расписанный балл.
 *
 * Шаги анкеты названы нейтрально («О тебе: часть N»): кандидат не должен
 * видеть, по каким характеристикам его оценивают.
 *
 * Отсюда берут сид нового сезона и `scripts/apply-portrait.ts` (перенос на
 * сайт, пока нет оценок и ответов). Дальше всё правится в «Анкета и оценка».
 */
import type { QuestionFormat, QuestionType } from "~~/lib/generated/prisma/enums";

export interface PortraitCriterion {
  title: string;
  description?: string;
  /** Общий список индикаторов — один на все баллы. */
  indicators?: string;
  maxScore: number;
  levels: { score: number; text: string }[];
}
export interface PortraitMarker {
  title: string;
  example: string;
}
export interface PortraitQuestion {
  section: string;
  type: QuestionType;
  label: string;
  help?: string;
  options?: string[];
  format?: QuestionFormat;
  required?: boolean;
  minLength?: number;
}
export interface PortraitSection {
  title: string;
  description?: string;
  homework?: boolean;
}

export const HOMEWORK_SECTION = "Домашнее задание";

